 * Safe linkifier for plain social-feed text.
 *
 * Turns @mentions, #hashtags and bare http(s) URLs into anchors.
 * All other text (and all token text) is HTML-escaped exactly once,
 * so the output is safe to drop into innerHTML.
 */

const ESCAPES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

/** Escape a string for HTML output, exactly once. */
function escapeHtml(s) {
  return s.replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

/**
 * Trim trailing punctuation from a bare URL without breaking balanced parens:
 * - trailing , ; . ! ? ' " are always stripped
 * - a trailing ')' is only stripped when its paren is unbalanced
 *   (Wikipedia-style URLs like .../Chicago_(band) keep their closing paren)
 */
function trimUrlPunctuation(url) {
  let u = url;
  for (;;) {
    const before = u;
    // strip simple trailing punctuation
    u = u.replace(/[,;:!?'".,]+$/, '');
    // balance parens: strip ')' if there is no matching '(' left inside the URL
    while (u.endsWith(')')) {
      const opens = (u.match(/\(/g) || []).length;
      const closes = (u.match(/\)/g) || []).length;
      if (closes > opens) u = u.slice(0, -1);
      else break;
    }
    if (u === before) return u;
  }
}

/**
 * Tokenizer: matches URLs first, then mentions, then hashtags.
 * Scanning is strictly left-to-right with no overlaps, so adjacent
 * tokens like "#a#b" both match and an email's "@" never becomes a mention
 * (the lookbehind rejects "@" preceded by word chars / handle characters).
 */
const TOKEN_RE = new RegExp(
  [
    /https?:\/\/[^\s<>"']+/.source, // 1: url (stops at whitespace or angle brackets)
    /(?<![\w.%+-])@([A-Za-z0-9_]+)/.source, // 2: mention handle
    /#([A-Za-z0-9_]+)/.source, // 3: hashtag
  ].join('|'),
  'g',
);

/**
 * @param {string} text plain text (may already contain nothing special — treat as raw)
 * @param {{mentionBase?: string, tagBase?: string}} opts
 *        mentionBase: prefix for profile links  (default "/users/")
 *        tagBase:     prefix for hashtag links  (default "/tags/")
 * @returns {string} HTML with anchors; everything escaped exactly once
 */
export function linkify(text, { mentionBase = '/users/', tagBase = '/tags/' } = {}) {
  const src = String(text ?? '');

  let out = '';
  let last = 0;
  TOKEN_RE.lastIndex = 0;

  let m;
  while ((m = TOKEN_RE.exec(src)) !== null) {
    out += escapeHtml(src.slice(last, m.index));

    if (m[1] !== undefined) {
      // URL
      const url = trimUrlPunctuation(m[1]);
      const href = escapeHtml(url);
      // advance past the trimmed URL so stripped punctuation is escaped as text
      TOKEN_RE.lastIndex = m.index + url.length;
      const display =
        url.length > 40 ? escapeHtml(url.slice(0, 40)) + '\u2026' : href;
      out += `<a href="${href}">${display}</a>`;
    } else if (m[2] !== undefined) {
      // Mention
      const name = m[2];
      const href = escapeHtml(mentionBase + encodeURIComponent(name));
      out += `<a href="${href}">@${escapeHtml(name)}</a>`;
    } else {
      // Hashtag
      const tag = m[3];
      const href = escapeHtml(tagBase + encodeURIComponent(tag));
      out += `<a href="${href}">#${escapeHtml(tag)}</a>`;
    }

    last = TOKEN_RE.lastIndex;
  }

  out += escapeHtml(src.slice(last));
  return out;
}

export default linkify;
"})
