result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/linkify/test/linkify.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { linkify } from '../src/linkify.js';

const OPTS = { mentionBase: 'https://social.test/u/', tagBase: 'https://social.test/tags/' };

function anchors(html) {
  const $ = cheerio.load(html);
  return $('a')
    .toArray()
    .map((a) => ({ href: $(a).attr('href'), text: $(a).text() }));
}

describe('linkify', () => {
  it('links a mention', () => {
    const html = linkify('hi @alice!', OPTS);
    expect(anchors(html)).toEqual([
      { href: 'https://social.test/u/alice', text: '@alice' },
    ]);
    expect(html.endsWith('!')).toBe(true);
  });

  it('links a hashtag', () => {
    const html = linkify('mood #sunny today', OPTS);
    expect(anchors(html)).toEqual([
      { href: 'https://social.test/tags/sunny', text: '#sunny' },
    ]);
  });

  it('links adjacent hashtags #a#b as two tokens', () => {
    const html = linkify('#a#b', OPTS);
    const as = anchors(html);
    expect(as).toHaveLength(2);
    expect(as[0]).toEqual({ href: 'https://social.test/tags/a', text: '#a' });
    expect(as[1]).toEqual({ href: 'https://social.test/tags/b', text: '#b' });
  });

  it('does NOT turn an email address into a mention', () => {
    const html = linkify('mail bob@smith.com please', OPTS);
    expect($('x', cheerio.load(html)) ? true : true).toBe(true); // noop guard
    expect(html).not.toContain('<a');
    // escaped exactly once, still plain text
    expect(html).toBe('mail bob@smith.com please');
  });

  it('trims trailing comma off a bare URL (comma)', () => {
    const html = linkify('see http://example.com/a/b, ok?', OPTS);
    expect(anchors(html)).toEqual([
      { href: 'http://example.com/a/b', text: 'http://example.com/a/b' },
    ]);
    expect(html).toContain(', ok?');
  });

  it('keeps balanced parens in wikipedia-style URLs, drops unbalanced ones', () => {
    // balanced: closing paren belongs to the URL
    const html1 = linkify(
      'wiki: http://en.wikipedia.org/wiki/Chicago_(band) is great',
      OPTS,
    );
    expect(anchors(html1)[0].href).toBe(
      'http://en.wikipedia.org/wiki/Chicago_(band)',
    );

    // wrapped in sentence parens: trailing ')' is NOT part of the URL
    const html2 = linkify('(see http://example.com/page)', OPTS);
    const a2 = anchors(html2);
    expect(a2[0].href).toBe('http://example.com/page');
    expect(html2.startsWith('(see <a')).toBe(true);
    expect(html2.endsWith(')</p>') || html2.endsWith(')')).toBe(true);
  });

  it('stops URLs at angle brackets and escapes them once', () => {
    const html = linkify('look <http://example.com/x> now', OPTS);
    expect(anchors(html)).toEqual([
      { href: 'http://example.com/x', text: 'http://example.com/x' },
    ]);
    expect(html).toContain('&lt;');
    expect(html).toContain('&gt;');
    expect(html).not.toContain('<h'); // raw stray tag would be suspicious
    expect(html.indexOf('&lt;')).toBeLessThan(html.indexOf('<a '));
  });

  it('truncates long URL display text to 40 chars + horizontal ellipsis', () => {
    const url =
      'https://example.com/very/long/path/that/goes/on/and/on/forever';
    const html = linkify(url, OPTS);
    const [a] = anchors(html);
    expect(a.href).toBe(url);
    expect(a.text.endsWith('\u2026')).toBe(true);
    expect(a.text.length).toBe(41); // 40 chars + ellipsis
    expect(a.text.startsWith('https://example.com/very/long/pat')).toBe(true);
  });

  it('keeps short URL display text identical to href', () => {
    const [a] = anchors(linkify('http://ex.co/a', OPTS));
    expect(a.text).toBe('http://ex.co/a');
  });

  it('escapes an ampersand near a mention EXACTLY once', () => {
    const html = linkify('Tom & @jerry #fun', OPTS);
    expect(html).toContain('Tom &amp; ');
    expect(html).not.toContain('&amp;amp;');
    const as = anchors(html);
    expect(as.map((a) => a.href)).toEqual([
      'https://social.test/u/jerry',
      'https://social.test/tags/fun',
    ]);
    // ampersand inside an escaped URL is also single-escaped
    const html2 = linkify('http://example.com/?a=1&b=2', OPTS);
    expect(anchors(html2)[0].href).toBe('http://example.com/?a=1&amp;b=2');
    expect(html2).not.toContain('&amp;amp;');
  });

  it('never emits raw angle brackets from input text (injection-safe)', () => {
    const html = linkify('<script>alert("x")</script> @bob', OPTS);
    expect(html).not.toContain('<script>');
    expect(html).toContain('&lt;script&gt;');
    expect(anchors(html)).toHaveLength(1);
  });

  it('handles a mixed real-world post', () => {
    const html = linkify(
      'Thanks @dana & team! Read http://en.wikipedia.org/wiki/Foo_(bar), then #shipit',
      OPTS,
    );
    const as = anchors(html);
    expect(as).toHaveLength(3);
    expect(as[0].href).toBe('https://social.test/u/dana');
    expect(as[1].href).toBe('http://en.wikipedia.org/wiki/Foo_(bar)');
    expect(as[2].href).toBe('https://social.test/tags/shipit');
    expect(html).toContain('&amp;');
  });
});
"})
